import{_ as i,W as o,s as l,u as d,I as p,ah as c,w as s,Z as e,A as t}from"./chunks/framework.Dx7wo2et.js";import"./chunks/theme.CjgFg8Ql.js";const y=JSON.parse('{"title":"Linux 中改变主机名的 4 种方法 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 中改变主机名的 4 种方法 | LCTT (201903) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 中改变主机名的 4 种方法 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 中改变主机名的 4 种方法 | LCTT (201903) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201903/20190215 4 Methods To Change The HostName In Linux","title":"Linux 中改变主机名的 4 种方法","tag":"201903"},"relativePath":"201903/20190215 4 Methods To Change The HostName In Linux.md","filePath":"[post].md"}'),h={name:"201903/20190215 4 Methods To Change The HostName In Linux.md"};function u(m,a,g,r,b,v){const n=o("Link");return d(),l("div",null,[a[18]||(a[18]=p("h1",{id:"linux-中改变主机名的-4-种方法",tabindex:"-1"},[s("Linux 中改变主机名的 4 种方法 "),p("a",{class:"header-anchor",href:"#linux-中改变主机名的-4-种方法","aria-label":"Permalink to Linux 中改变主机名的 4 种方法"},"​")],-1)),p("p",null,[a[1]||(a[1]=s("昨天我们已经在我们的网站中写过")),e(n,{href:"https://www.2daygeek.com/linux-change-set-hostname/"},{default:t(()=>a[0]||(a[0]=[s("如何在 Linux 中修改主机名的文章")])),_:1}),a[2]||(a[2]=s("。今天，我们将向你展示使用不同的方法来修改主机名。你可以从中选取最适合你的方法。"))]),a[19]||(a[19]=c(`<p>使用 <code>systemd</code> 的系统自带一个名为 <code>hostnamectl</code> 的好用工具，它可以使我们能够轻易地管理系统的主机名。</p><p>当你使用这个原生命令时，它可以立刻改变主机名而无需重启来生效。</p><p>但假如你通过手动修改某个配置文件来更改主机名，那么就可能需要经过重启来生效。</p><p>在这篇文章中，我们将展示在使用 <code>systemd</code> 的系统中改变主机名的 4 种方法。</p><p><code>hostnamectl</code> 命令允许在 Linux 中设置三类主机名，它们的细节如下：</p><ul><li><strong>静态：</strong> 这是静态主机名，由系统管理员添加。</li><li><strong>瞬时/动态：</strong> 这个由 DHCP 或者 DNS 服务器在运行时赋予。</li><li><strong>易读形式：</strong> 它可以由系统管理员赋予。这个是自由形式的主机名，以一种易读形式来表示服务器，例如 “JBOSS UAT Server” 这样的名字。</li></ul><p>这些都可以使用下面 4 种方法来设置。</p><ul><li><code>hostnamectl</code> 命令：控制系统主机名。</li><li><code>nmcli</code> 命令：是一个控制 NetworkManager 的命令行工具。</li><li><code>nmtui</code> 命令：是一个控制 NetworkManager 的文本用户界面。</li><li><code>/etc/hostname</code> 文件：这个文件中包含系统的静态主机名。</li></ul><h3 id="方法-1-在-linux-中使用-hostnamectl-来改变主机名" tabindex="-1">方法 1：在 Linux 中使用 hostnamectl 来改变主机名 <a class="header-anchor" href="#方法-1-在-linux-中使用-hostnamectl-来改变主机名" aria-label="Permalink to 方法 1：在 Linux 中使用 hostnamectl 来改变主机名">​</a></h3><p><code>hostnamectl</code> 可被用来查询和改变系统的主机名，以及相关设定。只需运行 <code>hostnamectl</code> 便可以查看系统的主机名了。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ hostnamectl</span></span></code></pre></div><p>或者使用下面的命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ hostnamectl status</span></span>
<span class="line"><span>   Static hostname: daygeek-Y700</span></span>
<span class="line"><span>         Icon name: computer-laptop</span></span>
<span class="line"><span>           Chassis: laptop</span></span>
<span class="line"><span>        Machine ID: 31bdeb7b83230a2025d43547368d75bc</span></span>
<span class="line"><span>           Boot ID: 267f264c448f000ea5aed47263c6de7f</span></span>
<span class="line"><span>  Operating System: Manjaro Linux</span></span>
<span class="line"><span>            Kernel: Linux 4.19.20-1-MANJARO</span></span>
<span class="line"><span>      Architecture: x86-64</span></span></code></pre></div><p>假如你想改变主机名，可以使用下面的命令格式：</p><p>语法格式：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ hostnamectl set-hostname [YOUR NEW HOSTNAME]</span></span></code></pre></div><p>使用下面的命令来使用 <code>hostnamectl</code> 更改主机名。在这个例子中，我将把主机名从 <code>daygeek-Y700</code> 改为 <code>magi-laptop</code>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ hostnamectl set-hostname magi-laptop</span></span></code></pre></div><p>你可以使用下面的命令来查看更新后的主机名。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ hostnamectl</span></span>
<span class="line"><span>   Static hostname: magi-laptop</span></span>
<span class="line"><span>         Icon name: computer-laptop</span></span>
<span class="line"><span>           Chassis: laptop</span></span>
<span class="line"><span>        Machine ID: 31bdeb7b83230a2025d43547368d75bc</span></span>
<span class="line"><span>           Boot ID: 267f264c448f000ea5aed47263c6de7f</span></span>
<span class="line"><span>  Operating System: Manjaro Linux</span></span>
<span class="line"><span>            Kernel: Linux 4.19.20-1-MANJARO</span></span>
<span class="line"><span>      Architecture: x86-64</span></span></code></pre></div><h3 id="方法-2-在-linux-中使用-nmcli-命令来更改主机名" tabindex="-1">方法 2：在 Linux 中使用 nmcli 命令来更改主机名 <a class="header-anchor" href="#方法-2-在-linux-中使用-nmcli-命令来更改主机名" aria-label="Permalink to 方法 2：在 Linux 中使用 nmcli 命令来更改主机名">​</a></h3><p><code>nmcli</code> 是一个命令行工具，旨在控制 NetworkManager 并报告网络状态。</p><p><code>nmcli</code> 被用来创建、展示、编辑、删除、激活和注销网络连接，同时还可以用来控制和展示网络设备的状态。另外，它也允许我们更改主机名。</p><p>使用下面的命令来利用 <code>nmcli</code> 查看当前的主机名。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ nmcli general hostname</span></span>
<span class="line"><span>daygeek-Y700</span></span></code></pre></div><p>语法格式：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ nmcli general hostname [YOUR NEW HOSTNAME]</span></span></code></pre></div><p>使用下面的命令来借助 <code>nmcli</code> 命令可以更改主机名。在这个例子中，我将把主机名从 <code>daygeek-Y700</code> 变成 <code>magi-laptop</code>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ nmcli general hostname magi-laptop</span></span></code></pre></div><p>它可以在不重启下设备的情况下生效，但为了安全目的，只需要重启 <code>systemd-hostnamed</code> 服务来使得更改生效。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo systemctl restart systemd-hostnamed</span></span></code></pre></div><p>再次运行相同的 <code>nmcli</code> 命令来检查更改后的主机名。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ nmcli general hostname</span></span>
<span class="line"><span>magi-laptop</span></span></code></pre></div><h3 id="方法-3-在-linux-中使用-nmtui-来更改主机名" tabindex="-1">方法 3：在 Linux 中使用 nmtui 来更改主机名 <a class="header-anchor" href="#方法-3-在-linux-中使用-nmtui-来更改主机名" aria-label="Permalink to 方法 3：在 Linux 中使用 nmtui 来更改主机名">​</a></h3><p><code>nmtui</code> 是一个基于 <code>curses</code> 库的 TUI 应用，被用来和 NetworkManager 交互。当启动 <code>nmtui</code> 后，如果没有指定 <code>nmtui</code> 的第一个命令行参数，它将提醒用户选择执行某项活动。</p><p>在终端中运行下面的命令来开启文本用户界面。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ nmtui</span></span></code></pre></div><p>使用向下箭头按键来选择 “Set system hostname” 这个选项，然后敲击回车键。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2019/02/four-methods-to-change-the-hostname-in-linux-1.png" alt=""></p><p>下面的截图展示的是原来的主机名。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2019/02/four-methods-to-change-the-hostname-in-linux-2.png" alt=""></p><p>我们需要做的就是删除原来的主机名，再输入新的主机名，然后选中 “OK” 敲击回车确认就可以了。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2019/02/four-methods-to-change-the-hostname-in-linux-3.png" alt=""></p><p>然后它将在屏幕中向你展示更新后的主机名，再次选中 “OK” 敲击回车确认就完成更改了。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2019/02/four-methods-to-change-the-hostname-in-linux-4.png" alt=""></p><p>最后，选中 “Quit” 按钮来从 <code>nmtui</code> 终端界面离开。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2019/02/four-methods-to-change-the-hostname-in-linux-5.png" alt=""></p><p>它可以在不重启设备的情况下生效，但为了安全目的，需要重启 <code>systemd-hostnamed</code> 服务来使得更改生效。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo systemctl restart systemd-hostnamed</span></span></code></pre></div><p>你可以运行下面的命令来查看更新后的主机名。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ hostnamectl</span></span>
<span class="line"><span>   Static hostname: daygeek-Y700</span></span>
<span class="line"><span>         Icon name: computer-laptop</span></span>
<span class="line"><span>           Chassis: laptop</span></span>
<span class="line"><span>        Machine ID: 31bdeb7b83230a2025d43547368d75bc</span></span>
<span class="line"><span>           Boot ID: 267f264c448f000ea5aed47263c6de7f</span></span>
<span class="line"><span>  Operating System: Manjaro Linux</span></span>
<span class="line"><span>            Kernel: Linux 4.19.20-1-MANJARO</span></span>
<span class="line"><span>      Architecture: x86-64</span></span></code></pre></div><h3 id="方法-4-在-linux-中使用-etc-hostname-来更改主机名" tabindex="-1">方法 4：在 Linux 中使用 /etc/hostname 来更改主机名 <a class="header-anchor" href="#方法-4-在-linux-中使用-etc-hostname-来更改主机名" aria-label="Permalink to 方法 4：在 Linux 中使用 /etc/hostname 来更改主机名">​</a></h3><p>除了上面的方法外，我们还可以通过修改 <code>/etc/hostname</code> 文件来达到修改主机名的目的。但这个方法需要服务器重启才能生效。</p><p>使用下面的命令来检查 <code>/etc/hostname</code> 文件以查看当前的主机名：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ cat /etc/hostname</span></span>
<span class="line"><span>daygeek-Y700</span></span></code></pre></div><p>要改变主机名，只需覆写这个文件就行了，因为这个文件只包含主机名这一项内容。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo echo &quot;magi-daygeek&quot; &gt; /etc/hostname</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ cat /etc/hostname</span></span>
<span class="line"><span>magi-daygeek</span></span></code></pre></div><p>然后使用下面的命令重启系统：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo init 6</span></span></code></pre></div><p>最后查看 <code>/etc/hostname</code> 文件的内容来验证主机名是否被更改了。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ cat /etc/hostname</span></span>
<span class="line"><span>magi-daygeek</span></span></code></pre></div><hr>`,62)),p("p",null,[a[4]||(a[4]=s("via: ")),e(n,{href:"https://www.2daygeek.com/four-methods-to-change-the-hostname-in-linux/"},{default:t(()=>a[3]||(a[3]=[s("https://www.2daygeek.com/four-methods-to-change-the-hostname-in-linux/")])),_:1})]),p("p",null,[a[9]||(a[9]=s("作者：")),e(n,{href:"https://www.2daygeek.com/author/magesh/"},{default:t(()=>a[5]||(a[5]=[s("Magesh Maruthamuthu")])),_:1}),a[10]||(a[10]=s(" 选题：")),e(n,{href:"https://github.com/lujun9972"},{default:t(()=>a[6]||(a[6]=[s("lujun9972")])),_:1}),a[11]||(a[11]=s(" 译者：")),e(n,{href:"https://github.com/FSSlc"},{default:t(()=>a[7]||(a[7]=[s("FSSlc")])),_:1}),a[12]||(a[12]=s(" 校对：")),e(n,{href:"https://github.com/wxy"},{default:t(()=>a[8]||(a[8]=[s("wxy")])),_:1})]),p("p",null,[a[15]||(a[15]=s("本文由 ")),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>a[13]||(a[13]=[s("LCTT")])),_:1}),a[16]||(a[16]=s(" 原创编译，")),e(n,{href:"https://linux.cn/"},{default:t(()=>a[14]||(a[14]=[s("Linux中国")])),_:1}),a[17]||(a[17]=s(" 荣誉推出"))])])}const C=i(h,[["render",u]]);export{y as __pageData,C as default};
